const items = $input.all();

// Default mock identity evidence for prototype bidders
const MOCK_IDENTITIES = {
  "ABC Technologies Pvt Ltd": {
    gst: {
      gstin: "27AABCU9603R1ZM",
      legal_name: "ABC Technologies Private Limited"
    },
    pan: {
      pan: "AABCU9603R",
      holder_name: "ABC Technologies Pvt Ltd"
    },
    udyam: {
      udyam_number: "UDYAM-MH-01-0012345",
      enterprise_name: "ABC Technologies Private Limited"
    },
    financial: {
      entity_name: "ABC Technologies Pvt Ltd"
    },
    documents: [
      {
        document_id: "DOC-GST-001",
        document_type: "GST_CERTIFICATE",
        entity_name: "ABC Technologies Private Limited"
      }
    ]
  }
};

return items.map(item => {
  const data = item.json.body || item.json;
  const errors = [];

  const requestId = data.request_id || "REQ-ENT-DEMO";
  const tenderId = data.tender_id || "TENDER-ENT-DEMO";
  const bidderId = data.bidder_id || "BIDDER-ENT-DEMO";
  const bidderName = (data.bidder_name || "").toString().trim();

  if (!bidderName) {
    errors.push("Missing required field 'bidder_name'");
  }

  let identityEvidence = data.identity_evidence;
  let evidenceProvided = false;

  if (identityEvidence && typeof identityEvidence === 'object') {
    evidenceProvided = true;
  } else {
    // Check if root-level statutory fields are supplied
    if (data.gstin || data.pan || data.udyam) {
      evidenceProvided = true;
      identityEvidence = {
        gst: data.gstin ? { gstin: data.gstin, legal_name: bidderName } : null,
        pan: data.pan ? { pan: data.pan, holder_name: bidderName } : null,
        udyam: data.udyam ? { udyam_number: data.udyam, enterprise_name: bidderName } : null
      };
    } else if (MOCK_IDENTITIES[bidderName]) {
      identityEvidence = MOCK_IDENTITIES[bidderName];
    } else {
      identityEvidence = {};
    }
  }

  return {
    json: {
      request_id: requestId,
      tender_id: tenderId,
      bidder_id: bidderId,
      bidder_name: bidderName,
      identity_evidence: identityEvidence,
      evidence_provided: evidenceProvided,
      valid_schema: errors.length === 0,
      validation_errors: errors,
      raw_input: data
    }
  };
});

const items = $input.all();

function normalizeLegalName(raw) {
  if (!raw || typeof raw !== 'string') return '';

  let s = raw.toUpperCase().trim();
  // Remove punctuation (dots, commas, hyphens, quotes, brackets)
  s = s.replace(/[.,'"\/#!$%^&*;:{}=\-_`~()]/g, ' ');
  // Collapse spaces
  s = s.replace(/\s+/g, ' ').trim();

  // Normalize common approved legal suffixes
  const suffixes = [
    /\bPRIVATE LIMITED\b/g,
    /\bPVT LTD\b/g,
    /\bPVT LIMITED\b/g,
    /\bLIMITED LIABILITY PARTNERSHIP\b/g,
    /\bLIMITED\b/g,
    /\bLTD\b/g,
    /\bLLP\b/g,
    /\bINCORPORATED\b/g,
    /\bINC\b/g,
    /\bCORPORATION\b/g,
    /\bCORP\b/g,
    /\bCOMPANY\b/g,
    /\bCO\b/g
  ];

  for (const suf of suffixes) {
    s = s.replace(suf, ' ');
  }

  return s.replace(/\s+/g, ' ').trim();
}

return items.map(item => {
  const data = item.json;
  if (!data.valid_schema) return { json: data };

  const rawBidder = data.bidder_name || '';
  const normBidder = normalizeLegalName(rawBidder);

  const ev = data.identity_evidence || {};
  const normEvidence = {};

  if (ev.gst) {
    normEvidence.gst = {
      ...ev.gst,
      normalized_name: normalizeLegalName(ev.gst.legal_name || ev.gst.trade_name || '')
    };
  }
  if (ev.pan) {
    normEvidence.pan = {
      ...ev.pan,
      normalized_name: normalizeLegalName(ev.pan.holder_name || ev.pan.entity_name || '')
    };
  }
  if (ev.udyam) {
    normEvidence.udyam = {
      ...ev.udyam,
      normalized_name: normalizeLegalName(ev.udyam.enterprise_name || '')
    };
  }
  if (ev.financial) {
    normEvidence.financial = {
      ...ev.financial,
      normalized_name: normalizeLegalName(ev.financial.entity_name || '')
    };
  }
  if (Array.isArray(ev.documents)) {
    normEvidence.documents = ev.documents.map(d => ({
      ...d,
      normalized_name: normalizeLegalName(d.entity_name || '')
    }));
  }

  return {
    json: {
      ...data,
      canonical_name: normBidder,
      normalized_evidence: normEvidence
    }
  };
});

const items = $input.all();

return items.map(item => {
  const data = item.json;
  if (!data.valid_schema) return { json: data };

  const canonical = data.canonical_name;
  const ev = data.normalized_evidence || {};

  const nameMatches = {};
  const sourcesEvaluated = [];
  const nameConflicts = [];

  // 1. GST legal name cross-check
  if (ev.gst && ev.gst.normalized_name) {
    sourcesEvaluated.push('GST');
    const match = ev.gst.normalized_name === canonical;
    nameMatches.gst = match;
    if (!match) {
      nameConflicts.push(`GST legal name ('${ev.gst.legal_name}') does not match bidder name ('${data.bidder_name}')`);
    }
  }

  // 2. PAN holder name cross-check
  if (ev.pan && ev.pan.normalized_name) {
    sourcesEvaluated.push('PAN');
    const match = ev.pan.normalized_name === canonical;
    nameMatches.pan = match;
    if (!match) {
      nameConflicts.push(`PAN holder name ('${ev.pan.holder_name}') does not match bidder name ('${data.bidder_name}')`);
    }
  }

  // 3. Udyam enterprise name cross-check
  if (ev.udyam && ev.udyam.normalized_name) {
    sourcesEvaluated.push('UDYAM');
    const match = ev.udyam.normalized_name === canonical;
    nameMatches.udyam = match;
    if (!match) {
      nameConflicts.push(`Udyam enterprise name ('${ev.udyam.enterprise_name}') does not match bidder name ('${data.bidder_name}')`);
    }
  }

  // 4. Financial entity name cross-check
  if (ev.financial && ev.financial.normalized_name) {
    sourcesEvaluated.push('FINANCIAL');
    const match = ev.financial.normalized_name === canonical;
    nameMatches.financial = match;
    if (!match) {
      nameConflicts.push(`Financial statements entity name ('${ev.financial.entity_name}') does not match bidder name ('${data.bidder_name}')`);
    }
  }

  // 5. Document entity names cross-check
  if (Array.isArray(ev.documents) && ev.documents.length > 0) {
    sourcesEvaluated.push('DOCUMENTS');
    let allDocsMatch = true;
    ev.documents.forEach(d => {
      if (d.normalized_name && d.normalized_name !== canonical) {
        allDocsMatch = false;
        nameConflicts.push(`Document '${d.document_id}' entity name ('${d.entity_name}') does not match bidder name ('${data.bidder_name}')`);
      }
    });
    nameMatches.documents = allDocsMatch;
  }

  return {
    json: {
      ...data,
      identity_sources_evaluated: sourcesEvaluated,
      name_matches: nameMatches,
      name_conflicts: nameConflicts
    }
  };
});

const items = $input.all();

const PAN_REGEX = /^[A-Z]{5}[0-9]{4}[A-Z]{1}$/;
const GSTIN_REGEX = /^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z]{1}[1-9A-Z]{1}Z[0-9A-Z]{1}$/;
const UDYAM_REGEX = /^UDYAM-[A-Z0-9-]+$/;

return items.map(item => {
  const data = item.json;
  if (!data.valid_schema) return { json: data };

  const ev = data.identity_evidence || {};
  const identifierChecks = {
    gst_pan_consistent: true,
    pan_format_valid: true,
    gstin_format_valid: true,
    udyam_format_valid: true
  };
  const identifierConflicts = [];

  const gstin = ev.gst?.gstin ? String(ev.gst.gstin).trim().toUpperCase() : null;
  const pan = ev.pan?.pan ? String(ev.pan.pan).trim().toUpperCase() : null;
  const udyam = ev.udyam?.udyam_number ? String(ev.udyam.udyam_number).trim().toUpperCase() : null;

  // 1. PAN format check
  if (pan) {
    const valid = PAN_REGEX.test(pan);
    identifierChecks.pan_format_valid = valid;
    if (!valid) {
      identifierConflicts.push(`Invalid PAN format: '${pan}'`);
    }
  }

  // 2. GSTIN format check
  if (gstin) {
    const valid = GSTIN_REGEX.test(gstin);
    identifierChecks.gstin_format_valid = valid;
    if (!valid) {
      identifierConflicts.push(`Invalid GSTIN format: '${gstin}'`);
    }
  }

  // 3. Udyam format check
  if (udyam) {
    const valid = UDYAM_REGEX.test(udyam);
    identifierChecks.udyam_format_valid = valid;
    if (!valid) {
      identifierConflicts.push(`Invalid Udyam registration format: '${udyam}'`);
    }
  }

  // 4. GSTIN ↔ PAN embedded relationship check
  if (gstin && pan) {
    // In Indian GSTIN, chars 2..12 (0-indexed) represent the 10-digit PAN
    if (gstin.length >= 12) {
      const embeddedPan = gstin.substring(2, 12);
      if (embeddedPan !== pan) {
        identifierChecks.gst_pan_consistent = false;
        identifierConflicts.push(`GSTIN PAN mismatch: GSTIN '${gstin}' contains embedded PAN '${embeddedPan}' which conflicts with submitted PAN '${pan}'`);
      } else {
        identifierChecks.gst_pan_consistent = true;
      }
    }
  }

  return {
    json: {
      ...data,
      identifier_checks: identifierChecks,
      identifier_conflicts: identifierConflicts
    }
  };
});

const items = $input.all();

return items.map(item => {
  const data = item.json;
  if (!data.valid_schema) return { json: data };

  const allConflicts = [];
  if (data.name_conflicts) allConflicts.push(...data.name_conflicts);
  if (data.identifier_conflicts) allConflicts.push(...data.identifier_conflicts);

  // Detect missing evidence
  const sources = data.identity_sources_evaluated || [];
  const hasIdentifiers = data.identity_evidence?.gst?.gstin || data.identity_evidence?.pan?.pan;

  if (sources.length === 0 && !hasIdentifiers) {
    allConflicts.push("Insufficient identity evidence provided for resolution");
  }

  return {
    json: {
      ...data,
      conflicts_detected: allConflicts
    }
  };
});

const items = $input.all();

return items.map(item => {
  const data = item.json;

  let status = "VERIFIED";
  let confidence = 0.98;
  let riskLevel = "LOW";
  const allIssues = [];

  if (!data.valid_schema) {
    status = "ERROR";
    confidence = 0.0;
    riskLevel = "HIGH";
    allIssues.push(...(data.validation_errors || ["Invalid entity input structure"]));
  } else {
    const conflicts = data.conflicts_detected || [];
    allIssues.push(...conflicts);

    const sources = data.identity_sources_evaluated || [];
    const identChecks = data.identifier_checks || {};

    if (conflicts.length > 0) {
      status = "NOT_VERIFIED";
      riskLevel = "HIGH";
      // Format errors decrease confidence
      if (!identChecks.pan_format_valid || !identChecks.gstin_format_valid) {
        confidence = 0.75;
      } else {
        confidence = 0.95;
      }
    } else if (sources.length === 0) {
      status = "NOT_VERIFIED";
      confidence = 0.85;
      riskLevel = "HIGH";
    } else {
      status = "VERIFIED";
      confidence = 0.99;
      riskLevel = "LOW";
    }
  }

  return {
    json: {
      agent: "ENTITY_RESOLUTION_AGENT",
      status,
      confidence,
      evidence: {
        bidder_id: data.bidder_id || "BIDDER-UNKNOWN",
        canonical_name: data.canonical_name || data.bidder_name || "",
        identity_sources_evaluated: data.identity_sources_evaluated || [],
        name_matches: data.name_matches || {},
        identifier_checks: data.identifier_checks || {
          gst_pan_consistent: true,
          pan_format_valid: true,
          gstin_format_valid: true,
          udyam_format_valid: true
        },
        conflicts_detected: data.conflicts_detected || [],
        registry_source: "BIDDER_SUBMISSION"
      },
      issues: allIssues,
      risk_level: riskLevel,
      timestamp: new Date().toISOString()
    }
  };
});

const items = $input.all();
return items.map(item => ({
  json: item.json
}));

const items = $input.all();
return items.map(item => ({
  json: {
    agent: "ENTITY_RESOLUTION_AGENT",
    status: "ERROR",
    confidence: 0.0,
    evidence: {
      error: "Entity resolution agent encountered an unexpected execution failure",
      fallback_mode: true
    },
    issues: ["Entity resolution agent failed unexpectedly"],
    risk_level: "HIGH",
    timestamp: new Date().toISOString()
  }
}));
